        "workflow": {
          "scope": "Report jobs run within the common workflow with independently verified publications; no arbitrary document-format import. An image block source may also be the verified typed PNG artifact of an earlier step (the WebP decodeToPng route): the artifact is accepted by kind only (text and image), captured and held to the plain-PNG limits, with the producer evidence verified again; trust is unsigned semantic consistency, and a producer PNG above 4 MiB is refused, not rescaled.",
          "references": [
            "docs/pandoc.md",
            "tools/qualify_pandoc.py",
            "tools/qualify_pandoc_image_artifact.py",
            "examples/schemaxis/pandoc-image-artifact.json",
            "examples/schemaxis/pandoc-image-artifact-epub.json"
          ]
        },
