          "scope": "Shared document references, pure expressions and finite visits resolve before report planning.",
          "references": [
            "docs/pandoc.md",
            "tools/qualify_pandoc.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://pandoc.org/MANUAL.html#creating-a-self-contained-web-page",
          "https://pandoc.org/MANUAL.html#option--sandbox",
          "https://github.com/jgm/pandoc-types/blob/master/src/Text/Pandoc/Definition.hs",
          "https://pandoc.org/MANUAL.html#option--extract-media",
          "https://pandoc.org/epub.html",
          "https://pandoc.org/MANUAL.html#option--to",
          "https://pandoc.org/MANUAL.html#metadata-variables",
          "https://pandoc.org/MANUAL.html#epub-metadata"
        ],
        "lifecycle": {
          "timeout": "One total deadline covers runtime/API probes, both writers, fresh readback and verification.",
          "cancellation": "Owned native processes use shared cancellation; check again before publication.",
          "logs": "Retain authored/effective plans, captured PNGs/digests, trusted AST, runtime, commands, stdout/stderr, HTML/DOCX, extracted readback media and failed/succeeded results. A transcript block also retains the captured segments.json bytes and their digest.",
          "verification": "Independent HTML parser and standard-library ZIP/OOXML relationships/cells/headings/image geometry/media checks compare with authored values; fresh Pandoc DOCX reader repeats the semantic check. Every image source is captured as a bounded regular file. A transcript block is validated at run time against its closed machine-draft or declared-reviewed contract, its captured bytes are bound by SHA-256 in the capture record, and the paragraph, table and provenance are recomputed from those bytes and compared with the trusted AST and with HTML, OOXML and fresh DOCX readback. With timeFormat the column headers and every start/end cell are recomputed from those bytes and the authored format, so an altered label, value or claimed format fails even when the receipt hashes are refreshed. With epub, the EPUB package is read by independent host code (exact physical ZIP framing with no prefix, suffix or hidden bytes and local headers equal to the central entries, stored mimetype first at offset 0 without extra field, bounded regular unique safe ZIP members, closed member set, container/OPF manifest, spine and navigation cross-references, pinned writer stylesheet, XHTML chapters with exact headings, paragraphs, table cells and PNG bytes, widths and alt text) and by a fresh Pandoc EPUB readback; scripts, external resources, DTDs, SVG, fonts and edited styles are refused."
        },
        "data": [
          {
            "id": "report",
            "direction": "output",
            "kind": "file",
            "format": "DOCX",
            "traits": {
              "content": "ordered headings/plain text/rectangular tables/embedded PNG"
            },
            "losses": [
